const registry=snapshot.registry as Raw;
// Declared registry facts first; an observation replaces one only where a collector recorded
// that exact field (OG-DATA-002). With no observation file the read model is byte-for-byte the
// v0.1 one, and freshness is evaluated here — at read time — never baked into the snapshot.
const observations=(snapshot.observations?.records??[]) as Observation[];
const readAt=new Date().toISOString();
const projects:Project[]=applyObservations(registry.projects.map((p:Raw)=>normalize(p,registry)),observations,readAt);
// Typed resource catalog (OG-REG-004/005, OG-MAP-002): derived from the pinned snapshot and the
// observations above. Nothing is fetched; a resource the registry does not declare does not exist.
const catalog=buildCatalog(registry,snapshot.sources,observations,loadEntities(entityFile,'config/entities.json'));
// Declared device records and the policy they live under (OG-DEV-001, OG-SEC-002). Both files
// are validated here exactly as the observer validates them: an employer-owned device may hold
// no capability, and no record may carry a machine identifier.
const policy=loadPolicy(policyFile,'config/policy.json');
const devices=loadDevices(deviceFile,policy,'config/devices.json');
// Connector definitions and connection records (OG-CONN-002). Validated at load exactly as the
// devices file is: a record that exceeds its connector's ceiling, claims a scope the connector
// does not declare, or carries anything credential-shaped stops the build.
const connections=loadConnectors(connectorFile,'config/connectors.json');
// Simulated inbox (OG-EVT-002). The only input is fixtures/events/*.json, validated against the
// docs/05 envelope at build time: a record naming a product the registry does not declare, an
// event type its connector never declared, or anything shaped like personal data stops the
// build. Duplicate provider deliveries are removed here, once, on (connector, provider_event_id).
const eventLog=loadEvents(rawFixtureEvents,'fixtures/events',{
 productIds:new Set(projects.map(p=>p.id)),
 connectorEvents:new Map(connections.connectors.map(c=>[c.id,c.events])),
});
const eventRows=inboxEvents(dedupe(eventLog)).sort(bySeverityThenTime);
const eventDuplicates=duplicatesOf(eventLog).length;
const eventFilters:EventFilters={...emptyEventFilters};
// Example action requests (OG-ACT-002). Every one is marked simulated and the loader refuses a
// record that is not; nothing in this application can execute one.
const actionRequests=loadActionRequests(actionRequestFile,'config/action-requests.json');
// Display denominators are DERIVED, never pinned. The one fail-closed pin is
// data/registry.lock.json, enforced by import-registry.mjs and the tests; those guards are
// what make these derived figures trustworthy, so the UI never needs a literal row count.
const snapshotDate=((d:string)=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(d);return m?`${Number(m[3])} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(m[2])-1]} ${m[1]}`:d;})(String(snapshot.asOf));
const artifactRows=projects.filter(p=>p.category==='NOT_A_PROJECT').length;
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const pretty=(s:string)=>s.replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
const badge=(kind:string,label=kind)=>`<span class="badge ${esc(kind.toLowerCase())}">${esc(label)}</span>`;
const factText=(f:Fact)=>`${f.truth??f.kind}${f.freshness?`, ${freshnessLabel[f.freshness]}`:''}${f.confidence?`, confidence ${f.confidence}`:''}`;
const evidence=(f:Fact)=>`<div class="fact"><span class="badge-row" role="group" aria-label="Evidence: ${esc(factText(f))}">${badge(f.kind)}${f.truth?badge(f.truth):''}${f.freshness&&f.freshness!=='not-collected'?badge(f.freshness==='stale'?'blocked':'observed',freshnessLabel[f.freshness]):''}${f.confidence?badge('inferred','confidence '+f.confidence):''}</span> <span>${esc(f.value)}</span>${f.state?`<small class="state ${esc(f.freshness??'')}">${esc(f.state)}</small>`:''}${f.note?`<small>${esc(f.note)}</small>`:''}<small class="source">${esc(f.source)}</small></div>`;
const icons=['▦','▤','⌘','⇄','◉','▣','✓','✉','☷','◷','◈','⊞'];
const views=['Portfolio','Project matrix','Ecosystem','Deployment drift','DayOS monitor','Devices','Requirements','Inbox','Approval queue','Timeline','KPI framework','Connectors'];
let view='Portfolio';
const filters:Filters={query:'',taxonomy:'',risk:'',status:'',evidence:''};
let notice='';
const storageKey='agoraxai.octopus.workflow.v1';
const fresh=():Workspace=>({version:1,entries:snapshot.approvalCandidates.map(c=>({id:c.id,title:c.title,stage:'PROPOSED',note:'Imported proposal only. Local simulation; no real approval or execution.',updatedAt:snapshot.asOf,demo:true})),log:[]});
let workspace=fresh();
try{const saved=localStorage.getItem(storageKey);if(saved){const parsed:unknown=JSON.parse(saved);if(validWorkspace(parsed)&&parsed.entries.length===workspace.entries.length&&parsed.entries.every(e=>workspace.entries.some(x=>x.id===e.id)))workspace=parsed;else notice='Stored simulation is invalid. Showing original proposals; no source data changed.';}}catch{notice='Local storage unavailable or invalid. Working in memory.';}
const app=document.querySelector<HTMLDivElement>('#app')!;
