 const visible=filterProjects(projects,filters);
 app.innerHTML=`<a class="skip" href="#content">Skip to content</a><aside class="sidebar"><a class="brand" href="#portfolio"><img src="${brandAssets.symbol}" alt="${esc(brandAlt.symbol)}" width="40" height="40" decoding="async"/><span>${esc(productName)}<small>${esc(productLine.toUpperCase())}</small></span></a><div class="edition"><span>OCTOPUSG</span><span>v0.2</span></div><nav aria-label="Main navigation">${views.map((v,i)=>`<button data-view="${v}" class="nav-item ${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icons[i]}</span>${v}${v==='Approval queue'?`<span class="count">${workspace.entries.length}</span>`:''}</button>`).join('')}</nav><div class="side-heading">ECOSYSTEM</div><nav aria-label="Taxonomy">${taxonomies.map(t=>`<button data-taxonomy="${esc(t)}" class="taxonomy-item ${filters.taxonomy===t?'active':''}">${esc(t)}<span>${projects.filter(p=>p.taxonomy===t).length}</span></button>`).join('')}</nav><div class="side-bottom"><span class="local-led"></span> Local workspace<small>Private · all connectors disabled</small></div></aside><div class="workspace"><header class="topbar"><span>Workspace <b>/</b> ${esc(view)}</span><div>${badge('local','LOCAL ONLY')}<span class="avatar" aria-label="Private workspace">AX</span></div></header><main id="content"><div class="heading">${view==='Portfolio'?`<div class="brand-plate"><img src="${brandAssets.logo}" alt="${esc(brandAlt.logo)}" width="600" height="570" decoding="async"/></div>`:''}<div><div class="eyebrow">AGORAXAI / INTERNAL PLATFORM</div><h1>${view==='Portfolio'?'Portfolio overview':esc(view)}</h1><p>${subtitles[view]||'Registry evidence, in one workspace.'}</p></div><div class="snapshot">Registry <b>v${registry.registry_version}</b><small>Snapshot · ${esc(snapshotDate)}</small></div></div>${notice?`<div role="status" class="banner">${esc(notice)}</div>`:''}${view==='Portfolio'?overview(visible):viewContent(view,visible)}</main><footer><span>${esc(productName)} — ${esc(productLine)} · private, local-only</span><span class="tagline">${esc(tagline)}</span><span>Observed in registry ≠ independently reverified now</span></footer></div><dialog id="detail" aria-labelledby="detail-title"></dialog>`;
 app.querySelectorAll<HTMLElement>('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view!;render();});
 app.querySelectorAll<HTMLElement>('[data-taxonomy]').forEach(b=>b.onclick=()=>{filters.taxonomy=filters.taxonomy===b.dataset.taxonomy?'':b.dataset.taxonomy!;view='Portfolio';render();});
 bindFilters();bindProjectDetails();bindView();
