function matrixRows(list:Project[]):string{return list.length?list.map(p=>`<tr><th scope="row"><button class="row-link" data-project="${p.id}">${esc(p.name)}</button><small>${esc(p.lifecycle)}</small>${badge(p.evidence)}</th><td>${evidence(p.path)}<details><summary>Recorded locations</summary><pre>${esc(JSON.stringify(p.raw.current_local_paths||p.raw.locations||[],null,2))}</pre></details></td><td>${evidence(p.repo)}</td><td>${evidence(p.url)}${['artemis-omni','dayos','pinarevleri','artemis-workbench','rainbow-botanics','prime-industrial-erp'].includes(p.id)?`<small>Shared host (observed): ${esc(registry.production_state.host)}</small>`:''}</td><td>${evidence(p.deployment)}</td><td>${evidence(p.backend)}</td><td>${badge(p.blockers.length?'blocked':'unknown')}<ul>${p.blockers.length?p.blockers.map(b=>`<li>${esc(b)}</li>`).join(''):'<li>No explicit blockers recorded</li>'}</ul></td><td>${evidence(p.nextAction)}</td></tr>`).join(''):'<tr><td colspan="8" class="empty">No matching rows. Reset the filters.</td></tr>';}
const driftBadge=(status:DriftStatus)=>badge(status==='match'?'observed':status==='differs'?'blocked':status==='stale'?'inferred':'unknown',status);
function localDriftRows(list:Project[]):string{
 return list.length?list.map(p=>{
  const rows=driftRows(p,observations,readAt,hostedSource(p.raw,registry));const status=worstStatus(rows);
  return `<tr data-drift-row="${p.id}"><th scope="row"><button class="row-link" data-project="${p.id}">${esc(p.name)}</button><small>${hasObservation(p,observations)?'observed locally':'no local observation'}</small></th>${rows.map(r=>`<td data-drift-field="${esc(r.field)}"><span class="badge-row" role="group" aria-label="${esc(r.label)}: ${esc(r.status)} — ${esc(driftMeaning[r.status])}; evidence ${esc(badgeText(r))}">${driftBadge(r.status)}${badge(r.truth)}</span><div class="fact"><span>declared: ${esc(r.declared)}</span><span>observed: ${esc(r.observed)}</span><small>${esc(r.state)}</small><small>${esc(r.note)}</small><small class="source">${esc(r.declaredSource)} · ${esc(r.observedSource)}</small></div></td>`).join('')}<td data-drift-summary="${esc(status)}">${driftBadge(status)}<p>${esc(driftMeaning[status])}</p></td></tr>`;
 }).join(''):'<tr><td colspan="5" class="empty">No matching rows. Reset the filters.</td></tr>';
}
function recordedDriftRows(list:Project[]):string{return list.length?list.map(p=>{const d=driftFor(p,registry,observations,readAt);return `<tr><th scope="row"><button class="row-link" data-project="${p.id}">${esc(p.name)}</button><small>${esc(p.deployment.value)}</small></th><td><code class="sha">${esc(d.sourceSha.value)}</code>${badge(d.sourceSha.kind)}<small>${esc(d.sourceBranch.value)}</small><small>${esc(d.sourceSha.source)}</small></td><td><code class="sha">${esc(d.productionSha.value)}</code>${badge(d.productionSha.kind)}</td><td>${badge(d.status==='Different SHAs'?'inferred':d.status==='Unknown'?'unknown':'observed',d.status)}<p>${esc(d.note)}</p></td></tr>`;}).join(''):'<tr><td colspan="4" class="empty">No matching rows. Reset the filters.</td></tr>';}
function mapView(){
 // Positions are computed from lanes here, at render time. No coordinate is stored in data, and
 // no coordinate carries meaning beyond layout (OG-MAP-003).
 const graph=selectGraph(projects,catalog,mapPreset,mapKind);
 const placed=layout(graph.nodes);
 const pos=new Map(placed.nodes.map(n=>[n.id,n]));
 const edges=graph.edges.filter(e=>pos.has(e.from)&&pos.has(e.to));
 const connected=new Set([mapSelected,...edges.filter(e=>e.from===mapSelected||e.to===mapSelected).flatMap(e=>[e.from,e.to])]);
 const legend=edgeLegend(edges.map(e=>e.truth));
 const viewWidth=placed.width,viewHeight=placed.height;
 const view=`${viewWidth/2-viewWidth/2/mapZoom} ${viewHeight/2-viewHeight/2/mapZoom} ${viewWidth/mapZoom} ${viewHeight/mapZoom}`;
 const controls=`<div class="map-controls"><label>Preset <select id="map-preset">${presets.map(p=>`<option value="${p}" ${mapPreset===p?'selected':''}>${p==='portfolio'?'Portfolio · products and relationships':'Repositories · products, repositories and checkouts'}</option>`).join('')}</select></label><label>Relationships <select id="map-kind"><option value="">All recorded relations</option>${options(mapPreset==='portfolio'?['dependency','ownership','historical']:['dependency','ownership','historical','resource'],mapKind)}</select></label><label>Colour by <select id="map-colour">${colourDimensions.map(d=>`<option value="${d}" ${mapColour===d?'selected':''}>${d==='risk'?'risk band':d==='truth'?'truth kind':'lifecycle'}</option>`).join('')}</select></label><label>Focus <select id="map-focus"><option value="">All ${projects.length} rows</option>${projects.map(p=>`<option value="${p.id}" ${mapSelected===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><button class="quiet" id="zoom-in" aria-label="Zoom in">+</button><button class="quiet" id="zoom-out" aria-label="Zoom out">−</button><button class="quiet" id="map-reset">Reset map</button><span id="map-legend">Edge style: ${esc(legend.join(' · '))||'no relationship shown'}</span></div>`;
 const laneBands=placed.lanes.map(l=>`<text x="16" y="${l.y-26}" class="map-caption" data-lane="${esc(l.lane)}">${esc(l.lane.toUpperCase())} · ${l.count}</text><line x1="8" y1="${l.y-18}" x2="${viewWidth-8}" y2="${l.y-18}" class="lane-rule"/>`).join('');
 const edgeShapes=edges.map(e=>{const a=pos.get(e.from)!,b=pos.get(e.to)!;const dash=edgeDash[e.truth]??'';
  return `<path class="edge ${esc(e.type)} truth-${esc(e.truth)} ${mapSelected&&!connected.has(e.to)?'dim':''}" data-edge="${esc(e.type)}" data-truth="${esc(e.truth)}" ${dash?`stroke-dasharray="${dash}"`:''} d="M${a.x},${a.y+27} C${a.x},${(a.y+b.y)/2} ${b.x},${(a.y+b.y)/2} ${b.x},${b.y-32}" marker-end="url(#arrow)"><title>${esc(e.type)} · ${esc(e.truth)} (${esc(edgeStyleLabel[e.truth]??'solid')} line) · ${esc(e.label)} · ${esc(e.source)}</title></path>`;}).join('');
 const nodeShapes=placed.nodes.map(n=>{const short=n.label.length>26?n.label.slice(0,25)+'…':n.label;
  return `<g class="map-node ${esc(n.kind)} ${esc(colourClass(n,mapColour))} ${mapSelected===n.id?'selected':''} ${mapSelected&&!connected.has(n.id)?'dim':''}" transform="translate(${n.x-108},${n.y-31})" role="button" tabindex="0" data-node="${esc(n.id)}" data-kind="${esc(n.kind)}" data-colour="${esc(colourValue(n,mapColour))}" aria-label="Focus ${esc(n.label)} · ${esc(n.kind)} · ${esc(mapColour)} ${esc(colourValue(n,mapColour))}"><rect width="216" height="64" rx="8"/><text x="12" y="24">${esc(short)}</text><text x="12" y="44" class="map-meta">${esc(n.kind==='product'?colourValue(n,mapColour):n.kind+' · '+colourValue(n,mapColour))}</text></g>`;}).join('');
 const label=(id:string)=>placed.nodes.find(n=>n.id===id)?.label??id;
 return `${controls}<div class="map-shell"><svg class="ecosystem-map" viewBox="${view}" role="group" aria-label="Generated ecosystem map, ${esc(mapPreset)} preset, coloured by ${esc(mapColour)}"><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>${laneBands}${edgeShapes}${nodeShapes}</svg></div><div class="panel"><h2>${mapSelected?esc(label(mapSelected)):'Relationship evidence'}</h2><p class="muted">Lanes and positions are generated from the registry: no coordinate is stored, and position carries no meaning beyond grouping. Atlas and Artemis are sibling platforms. Lines show only explicit recorded relationships, each with its type, truth kind and source; an isolated node means no relationship is declared, not that none exists. Edge style also encodes truth (${esc(legend.join(' · ')||'none shown')}), so colour is never the only channel.</p><ul class="edge-list">${edges.filter(e=>!mapSelected||e.from===mapSelected||e.to===mapSelected).map(e=>`<li><b>${esc(label(e.from))} → ${esc(label(e.to))}</b> ${badge(e.truth)} ${badge('inferred',e.type)}<p>${esc(e.label)}<small>${esc(edgeStyleLabel[e.truth]??'solid')} line · ${esc(e.source)}</small></p></li>`).join('')||'<li>No relationship of this type is recorded for this row.</li>'}</ul>${mapSelected&&projects.some(p=>p.id===mapSelected)?`<button class="primary" data-project="${mapSelected}">Open project evidence</button>`:''}</div>`;
}
// Devices are DECLARED records (OG-UI-004). Nothing here is measured, and the records carry no
// hostname, user name, serial number, IP or MAC address — `loadDevices` refuses any such field.
// DayOS monitor (OG-OBS-007). Read-only: every value below is already in the registry, the
// local observation file, the connection records or the simulated fixtures. Nothing is fetched.
const stateBadge=(s:MonitorState)=>badge(s,s.replace('-',' '));
const driftCell=(status:DriftStatus)=>driftBadge(status);
function monitorRowHtml(r:MonitorRow){
 const when=r.observedAt?`observed ${esc(r.observedAt)}${r.expiresAt?` · expires ${esc(r.expiresAt)}`:''}`:'';
 return `<tr data-monitor-row="${esc(r.id)}" data-state="${esc(r.state)}"${r.drift?` data-drift="${esc(r.drift)}"`:''}><th scope="row">${esc(r.label)}</th>
<td><span class="badge-row" role="group" aria-label="${esc(r.label)}: ${esc(r.state)} — ${esc(monitorStateMeaning[r.state])}; truth ${esc(r.truth)}">${stateBadge(r.state)}${r.truth!==r.state?badge(r.truth):''}${r.drift?driftCell(r.drift):''}</span>
<div class="fact"><span><code>${esc(r.value)}</code></span>${r.declared&&r.declared!==r.value?`<small>declared: ${esc(r.declared)}</small>`:''}${when?`<small>${when}</small>`:''}<small>${esc(r.note)}</small><small class="source">${esc(r.source)}</small></div></td></tr>`;
}
function monitorView():string{
 const p=projects.find(x=>x.id==='dayos');
 const report=p?monitorFor(p,registry,observations,connections,readAt):null;
 if(!p||!report)return '<div class="banner"><b>Nothing to monitor.</b> The registry declares no DayOS row, so no monitor is shown and none is invented.</div>';
 const c=report.collection;
 const gate=canObserve(devices,policy,allowlistFile.deviceId);
 const allowlisted=(allowlistFile.targets as {productId:string}[]).some(t=>t.productId===p.id)&&gate.ok;
 const actions=monitorActions(report,{allowlisted,reason:gate.ok?`${p.id} is not in config/observe.allowlist.json, so the opener refuses it.`:gate.reason});
 const events=eventRows.filter(e=>e.subject.product_id===p.id);
 const resources=resourcesOf(catalog,p.id);
 return `<div class="banner" data-collection="${esc(c.state)}"><b>${esc(report.name)} · collection ${esc(c.state.replace('-',' '))}.</b> ${esc(report.verdict)}<br>Observed at <b>${esc(c.observedAt??'never')}</b> · expires <b>${esc(c.expiresAt??'n/a')}</b> · source <code>${esc(c.source)}</code><br>${esc(c.detail)}</div>
<div class="section-heading"><h2>Local drift <span>${driftBadge(report.drift)}</span></h2><span>Declared registry value vs the owner-run observer</span></div>
<p class="muted">${esc(driftMeaning[report.drift])}. Registry <b>v${esc(registry.registry_version)}</b>, snapshot ${esc(snapshotDate)}; the page was read ${esc(readAt)}. No provider, database or network is contacted.</p>
${report.sections.map(sec=>`<div class="panel" data-monitor-section="${esc(sec.id)}"><h2>${esc(sec.title)}</h2><div class="table-scroll" tabindex="0" aria-label="${esc(sec.title)}, scrollable"><table class="monitor"><thead><tr><th scope="col">Field</th><th scope="col">State, truth and provenance</th></tr></thead><tbody>${sec.rows.map(monitorRowHtml).join('')}</tbody></table></div></div>`).join('')}
<div class="panel"><h2>Open actions ${badge('declared')}</h2><ul class="reason-list" id="monitor-actions">${actions.map(a=>`<li data-open="${esc(a.kind)}" data-enabled="${a.enabled}" aria-label="${esc(openSummary(a))}">${badge(a.truth)} <b>${esc(a.label)}</b> ${a.href?`<a href="${esc(a.href)}" rel="${linkAttributes.rel}" target="${linkAttributes.target}">${esc(a.text)}</a>`:`<code data-copy-path="${esc(a.text)}">${esc(a.text)}</code> <button class="quiet" data-copy="${esc(a.text)}">Copy</button>`}<small>${esc(a.note)}</small><small class="source">${esc(a.source)}</small></li>`).join('')||'<li>No source is established for this product, so there is nothing safe to open.</li>'}</ul><p class="muted">No website is declared for DayOS, so none is offered. Nothing here starts, deploys, migrates or changes anything.</p></div>
<div class="panel"><h2>Resource graph ${badge('derived')}</h2><ul class="reason-list" id="monitor-resources">${resources.map(r=>`<li data-resource="${esc(r.id)}">${badge(r.truth)} <b>${esc(r.kind)}</b> ${esc(r.label)}${r.note?`<small>${esc(r.note)}</small>`:''}<small class="source">${esc(r.id)} · ${esc(r.source)}</small></li>`).join('')||'<li>No resource is declared for this product.</li>'}</ul><p class="muted">The same typed catalog the Ecosystem map draws. Choose the Repository preset there to see these as nodes.</p></div>
<div class="panel"><h2>Inbox signals ${badge('inferred','SIMULATED')}</h2><ul class="reason-list" id="monitor-events">${events.map(e=>`<li data-event="${esc(e.id)}">${badge(e.severity==='critical'||e.severity==='warning'?'blocked':'observed',e.severity)} ${isSimulated(e)?badge('inferred','SIMULATED'):''} <b>${esc(e.type)}</b> ${esc(e.summary)}<small>${esc(e.occurred_at)} · not counted · ${esc(e.source.connector)}</small></li>`).join('')||'<li>No inbox event names this product.</li>'}</ul><p class="muted">These rows come from <code>fixtures/events/*.json</code>. They are rehearsal data: they do not feed the drift, the states above or any KPI.</p></div>
<div class="panel"><h2>What the states mean</h2><ul id="monitor-legend">${monitorStates.map(s=>`<li>${stateBadge(s)} ${esc(monitorStateMeaning[s])}</li>`).join('')}</ul></div>`;
}
function devicesView(){
 const zone=(id:string)=>policy.trustZones.find(z=>z.id===id);
 const row=(d:Device)=>{
  const z=zone(d.trustZone);
  const observe=canObserve(devices,policy,d.id);
  return `<tr data-device="${esc(d.id)}"><th scope="row">${esc(d.alias)}<small>${esc(d.id)}</small></th><td>${badge(d.ownership==='employer'?'blocked':'declared',d.ownership)}<small>${esc(z?.label??d.trustZone)}</small></td><td>${badge(d.enrolled?'observed':'unknown',d.enrolled?'enrolled':'not enrolled')}<small>${esc(d.accessModel)}</small></td><td>${d.capabilities.length?d.capabilities.map(c=>`<span class="badge declared">${esc(c)}</span> `).join(''):badge('unknown','none')}</td><td>${d.prohibited.map(c=>`<span class="badge blocked">${esc(c)}</span> `).join('')}</td><td data-observe="${observe.ok?'yes':'no'}">${badge(observe.ok?'observed':'blocked',observe.ok?'may observe':'never observed')}<p>${esc(observe.reason)}</p></td></tr>`;
 };
 const tierRows=policy.tiers.map(t=>`<tr><th scope="row">${esc(t.id)} ${esc(t.name)}<small>${esc(t.examples)}</small></th><td>${esc(String(t.minLevel))}</td><td>${esc(String(t.maxLevel))}${t.maxLevel<4?'<small>level 4 never applies</small>':''}</td><td>${esc(t.approval)}</td>${levels.map(l=>`<td data-tier="${esc(t.id)}" data-level="${l}" data-allowed="${evaluate(policy,{tier:t.id,level:l,approvalRecorded:true,templated:true,preconditionsMet:true}).allowed?'yes':'no'}">${evaluate(policy,{tier:t.id,level:l,approvalRecorded:true,templated:true,preconditionsMet:true}).allowed?badge('observed','allowed'):badge('unknown','no')}</td>`).join('')}</tr>`).join('');
 return `<div class="banner">Declared devices only. Nothing on this screen is measured from a machine: no host name, user name, serial number, IP or MAC address is recorded anywhere in OctopusG, and an employer-owned device may hold no capability and is never observed. Enrolment and local actions beyond read-only Git observation arrive in v0.5.</div><div class="section-heading"><h2>Devices <span id="device-count">${devices.devices.length}</span></h2><span>Declared · trust zones from config/policy.json</span></div><div class="table-scroll" tabindex="0" aria-label="Declared devices, scrollable"><table id="devices"><thead><tr><th scope="col">Device</th><th scope="col">Ownership / zone</th><th scope="col">Enrolment</th><th scope="col">Capabilities</th><th scope="col">Prohibited</th><th scope="col">Local observation</th></tr></thead><tbody>${devices.devices.map(row).join('')}</tbody></table></div><div class="section-heading"><h2>Action tiers and connection levels</h2><span>Policy as data · nothing here executes</span></div><div class="table-scroll" tabindex="0" aria-label="Action tiers and levels, scrollable"><table id="tiers"><thead><tr><th scope="col">Tier</th><th scope="col">Minimum level</th><th scope="col">Maximum level</th><th scope="col">Approval</th>${levels.map(l=>`<th scope="col">L${l}</th>`).join('')}</tr></thead><tbody>${tierRows}</tbody></table></div><p class="muted">Every approval in v0.2 is a labelled simulation: this table states what the policy <i>would</i> permit. Tiers ${esc(tierIds.join(', '))} and levels ${esc(levels.join(', '))} come from <code>config/policy.json</code>.</p>`;
}
// Requirements and capability status (OG-UI-005), generated from REQUIREMENTS.yaml at build time.
function requirementsView(){
 const reqs=requirementsData.requirements;
 const byMilestone=requirementsData.milestones.map(m=>({...m,rows:reqs.filter(r=>r.milestone===m.id)})).filter(m=>m.rows.length);
 const statuses=['PROPOSED','APPROVED','IMPLEMENTED','VERIFIED','DEFERRED','REJECTED'];
 const counts=(rows:typeof reqs)=>statuses.map(s=>`${s} ${rows.filter(r=>r.status===s).length}`).filter(t=>!t.endsWith(' 0')).join(' · ')||'none';
 const statusBadge=(s:string)=>badge(s==='VERIFIED'?'observed':s==='IMPLEMENTED'?'declared':s==='DEFERRED'||s==='REJECTED'?'blocked':'unknown',s);
 const capRow=(c:typeof requirementsData.capabilities[number])=>`<tr data-capability="${esc(c.id)}"><th scope="row">${esc(c.id)}<small>${esc(c.title)}</small></th><td>${badge(c.status==='AVAILABLE'?'observed':c.status==='CONCEPT'||c.status==='DEFERRED'?'unknown':'declared',c.status)}</td><td>${esc(c.target)}</td><td>${c.requirements.map(id=>`<a href="#req-${esc(id)}">${esc(id)}</a>`).join(' · ')}</td></tr>`;
 const reqRow=(r:typeof reqs[number])=>`<tr id="req-${esc(r.id)}" data-requirement="${esc(r.id)}" data-status="${esc(r.status)}"><th scope="row">${esc(r.id)}<small>${esc(r.title)}</small></th><td>${esc(r.plane)}<small>${esc(r.workPackage??'—')}</small></td><td>${statusBadge(r.status)}<small>${esc(r.milestone)}</small></td><td>${r.dependencies.length?r.dependencies.map(d=>esc(d)).join(', '):'none'}</td><td><ul>${r.acceptance.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>${r.acceptanceProvisional?'<small>Provisional: criteria are rewritten at the start of that block.</small>':''}</td><td>${r.tests.map(t=>`<code>${esc(t)}</code>`).join('<br>')}</td><td>${r.evidence.length?r.evidence.map(e=>esc(e)).join('<br>'):badge('unknown','none yet')}</td></tr>`;
 return `<div class="banner">Generated from <code>docs/requirements/REQUIREMENTS.yaml</code> at build time by <code>npm run spec:write</code>. This view is read-only: it changes nothing and cannot approve anything. Status values are the ledger's own — <b>VERIFIED</b> is set by the owner at a gate, never by an implementer.</div><div class="section-heading"><h2>Capabilities <span>${requirementsData.capabilities.length}</span></h2><span>capability → requirements → evidence</span></div><div class="table-scroll" tabindex="0" aria-label="Capability status, scrollable"><table id="capabilities"><thead><tr><th scope="col">Capability</th><th scope="col">Status</th><th scope="col">Target</th><th scope="col">Requirements</th></tr></thead><tbody>${requirementsData.capabilities.map(capRow).join('')}</tbody></table></div>${byMilestone.map(m=>`<div class="section-heading"><h2>${esc(m.id)} — ${esc(m.title)} <span id="count-${esc(m.id)}">${m.rows.length}</span></h2><span>${esc(counts(m.rows))}</span></div><div class="table-scroll" tabindex="0" aria-label="Requirements for ${esc(m.id)}, scrollable"><table class="requirements"><thead><tr><th scope="col">Requirement</th><th scope="col">Plane / WP</th><th scope="col">Status / milestone</th><th scope="col">Depends on</th><th scope="col">Acceptance criteria</th><th scope="col">Tests</th><th scope="col">Evidence</th></tr></thead><tbody>${m.rows.map(reqRow).join('')}</tbody></table></div>`).join('')}<p class="muted">${reqs.length} requirements · ${requirementsData.capabilities.length} capabilities · ledger updated ${esc(requirementsData.updated)}. Traceability runs capability → requirement → tests → evidence file; a requirement with no evidence file yet says so.</p>`;
}
function queueView(){return `<div class="banner simulation"><b>LOCAL SIMULATION · no real approvals or execution.</b> The 22 source proposals start at PROPOSED. Stage changes are browser-local annotations. OWNER_APPROVED is a simulated state with no authenticated owner identity; EXECUTING invokes no action. Source documents remain immutable.</div><div class="stages">${stages.map((s,i)=>`<span>${i?'→ ':''}${s}</span>`).join('')}</div><div class="section-heading"><h2>Gate 3 proposals <span>22</span></h2><div><button class="quiet" id="export-log">Export simulation</button> <button class="quiet" id="reset-workflow">Reset simulation</button></div></div><div class="table-scroll"><table><thead><tr><th>Proposal</th><th>Local simulation stage</th><th>Last note</th><th>Review</th></tr></thead><tbody>${workspace.entries.map(e=>`<tr><th scope="row"><span class="proposal-id">${e.id}</span>${esc(e.title)}</th><td>${badge('inferred',e.stage)}<small>SIMULATION ONLY</small></td><td>${esc(e.note)}</td><td><button class="quiet" data-workflow="${e.id}">Review proposal</button></td></tr>`).join('')}</tbody></table></div>${actionPolicyPanel()}`;}

// OG-ACT-002 rendered as outcomes rather than prose: each example request is run through the
// same pure decision the tests use, and the reason is printed exactly as the function returns it.
function actionPolicyPanel(){
 return `<div class="section-heading"><h2>Action requests · tier and level policy</h2><span>Evaluated, never executed</span></div>
<p class="muted">Each row below is an example request run through <code>decide()</code> — the same pure function <code>tests/policy.test.ts</code> asserts against. The verdict answers only "would this be permitted?". v0.2 contains no executor, and every request is marked <b>simulated</b>.</p>
<div class="table-scroll" tabindex="0" aria-label="Action request policy, scrollable"><table id="action-requests"><thead><tr>${['Request','Tier','Level','Verdict','Why'].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${actionRequests.map(r=>{
 const d=decide(policy,r,connections);
 return `<tr data-request="${esc(r.id)}" data-allowed="${d.allowed}"><th scope="row"><span class="badge-row" role="group" aria-label="${esc(decisionLine(r,d))}">${badge(d.allowed?'observed':'blocked',d.allowed?'would be permitted':'would be refused')}${badge('inferred','SIMULATED')}</span>${esc(r.title)}<small>${esc(r.id)}</small></th><td>${esc(r.tier)}</td><td>${r.level}</td><td>${d.allowed?'permitted':'refused'}</td><td>${esc(d.reason)}${d.ceiling?`<small>${esc(d.ceiling)}</small>`:''}${d.missing.length?`<small>missing: ${d.missing.map(f=>esc(dossierLabels[f])).join(' · ')}</small>`:''}</td></tr>`;
}).join('')}</tbody></table></div>
<div class="panel"><h2>What a T3 or T4 request must contain</h2><p>docs/06 §3, in order. All seven are required before a production or critical action may be approved; a missing field refuses the request even when the tier, level, zone and approval all pass.</p><ol class="dossier">${dossierFields.map(f=>`<li data-field="${esc(f)}">${esc(dossierLabels[f])}</li>`).join('')}</ol><p class="muted">An AI recommendation is never sufficient on its own. A present field is owner-supplied text, not proof: OctopusG checks that the record exists, not that it is true. ${dossierRequiredFor('T3')?'T3 and T4 require the full record; T0–T2 do not.':''}</p></div>`;}
function showWorkflow(id:string){const e=workspace.entries.find(e=>e.id===id)!;const candidate=snapshot.approvalCandidates.find(c=>c.id===id)!;const d=app.querySelector<HTMLDialogElement>('#detail')!;d.innerHTML=`<div class="dialog-top">${badge('inferred','Local simulation')}<button class="quiet" id="close-detail" aria-label="Close details">✕</button></div><h2 id="detail-title">${esc(e.id+' · '+e.title)}</h2><div class="banner simulation">Source status: proposed, not authorized. Notes and stage changes affect only this browser’s simulated queue.</div><h3>Original checklist evidence</h3><pre>${esc(candidate.evidence)}</pre><p class="muted">${esc(candidate.source)}</p>${nextStages(e.stage).length?`<form id="workflow-form"><label>Next simulated stage<select name="stage" required>${nextStages(e.stage).map(s=>`<option>${s}</option>`).join('')}</select></label><label>Evidence / decision note<textarea name="note" rows="4" required minlength="8" maxlength="2000" placeholder="Describe the simulated evidence or decision. Do not enter secrets."></textarea></label><p id="form-error" role="alert"></p><button class="primary" type="submit">Save simulated transition</button></form>`:'<p>This simulation has reached a terminal state. Reset the simulation to rehearse again.</p>'}`;d.showModal();d.querySelector<HTMLButtonElement>('#close-detail')!.onclick=()=>d.close();const form=d.querySelector<HTMLFormElement>('#workflow-form');if(form)form.onsubmit=event=>{event.preventDefault();const data=new FormData(form);try{workspace=transition(workspace,id,data.get('stage') as Stage,String(data.get('note')));try{localStorage.setItem(storageKey,JSON.stringify(workspace));notice='Simulated transition saved locally. No external action occurred.';}catch{notice='Simulation updated in memory. Browser storage is unavailable; export to retain it.';}d.close();render();}catch(error){d.querySelector('#form-error')!.textContent=(error as Error).message;}};}
function timelineView(){return `<div class="section-heading"><h2>Registry history</h2>${badge('observed','Recorded evidence')}</div><div class="timeline">${registry.migration_waves.map((w:Raw)=>`<article><div class="time-label">Gate ${esc(w.gate)}</div><div><h3>${esc(w.name||'Governance milestone')}</h3><p>${esc(w.status||'Future gate · exit criteria defined; completion unavailable')}</p><small>registry.migration_waves · ${w.gate==='2C'?'2026-09-15':w.gate==='2D'?'2026-09-15':'Exact event timestamp unavailable'}</small></div></article>`).join('')}</div><div class="panel"><h2>Gate 2C recorded actions</h2>${registry.gate_2c.completed_actions.map((a:Raw)=>`<p><b>${esc(a.id)}</b> · ${esc(a.project)} ${badge('observed','Verified at Gate 2D')}<small class="block">Recorded post-state: ${esc(JSON.stringify(a.post))}</small></p>`).join('')}<div class="banner">Evidence integrity remains OPEN: both recorded evidence folders have a missing manifested summary. This does not undo recorded verification, and must remain visible to future reviewers.</div></div><div class="section-heading"><h2>Local simulation log <span>${workspace.log.length}</span></h2>${badge('inferred','Demo activity')}</div>${workspace.log.length?`<div class="timeline">${[...workspace.log].reverse().map(l=>`<article><div class="time-label">${esc(l.at)}</div><div><h3>${esc(l.itemId)} · ${l.from} → ${l.to}</h3><p>${esc(l.note)}</p><small>Browser-local simulation · no external action · not a trusted audit trail</small></div></article>`).join('')}</div>`:'<div class="empty">No simulated actions yet. Review a proposal in the approval queue to add a local log entry.</div>'}`;}
function kpiView(){const measured=[['Registry coverage',`${projects.length} / ${registry.project_row_count}`,'Parsed rows / declared row count. Retirement requires explicit evidence.'],['Verified evidence coverage',`${projects.filter(p=>p.evidence==='observed').length} / ${projects.length}`,'Rows whose registry evidence_level begins with verified / all rows. Includes the security artifact.'],['Known source-to-production comparisons',`${projects.filter(p=>{const d=driftFor(p,registry,observations,readAt);return d.sourceSha.kind!=='unknown'&&d.productionSha.kind!=='unknown';}).length} / ${projects.length}`,'Rows with both recorded source and shared-host production SHAs; does not imply a release target.'],['Unresolved constraints',String(projects.filter(p=>p.blockers.length).length)+' rows','Rows with explicit blockers, unmet transition prerequisites, or special recorded exposures.']];const missing=[['Availability','Successful controlled HTTP probes / scheduled probes','HTTP uptime','Service owner','Rolling 30 days'],['Deployment frequency','Verified production deployments / period','Vercel','Release owner','Calendar week'],['Change failure rate','Production deployments requiring remediation / total','Vercel + incident register','Release owner','Rolling 30 days'],['Recovery time','Median verified recovery time − incident start time','Incident register','Service owner','Rolling 90 days'],['Infrastructure spend','Sum of invoiced service usage in a stated currency','Billing export (separate scope)','Finance owner','Calendar month'],['Active users','Distinct consenting active user IDs / period','Approved analytics source','Product owner','Rolling 30 days'],['Approval lead time','Median owner decision timestamp − proposal timestamp','Authenticated approval store','Portfolio owner','Calendar month']];return `<div class="banner">All-registry inventory metrics, including external clients, are calculated from registry v${registry.registry_version}; these are not internal ownership totals. Operational metrics have no connected source and remain unavailable. Simulation events are excluded from real KPI calculations.</div><div class="kpi-grid">${measured.map(([name,value,rule])=>`<article class="panel"><span class="muted">${name}</span><strong>${value}</strong>${badge('inferred','Calculated from snapshot')}<p>${rule}</p></article>`).join('')}</div><h2>Operational measurement plan</h2><div class="table-scroll"><table><thead><tr><th>Metric</th><th>Value / target</th><th>Definition</th><th>Required source</th><th>Proposed owner / window</th></tr></thead><tbody>${missing.map(([name,definition,source,owner,period])=>`<tr><th scope="row">${name}</th><td>${badge('unknown','Unavailable')}<small>Target not agreed</small></td><td>${definition}</td><td>${source}</td><td>${owner}<small>${period} · proposed</small></td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>Evidence health methodology</h2><p>Risk is the capped sum of documented signals. Evidence health is 100 − risk. Scores are inferred prioritization aids, never operational health or security clearance.</p><ul><li>Unknown project evidence: +30; reported evidence: +15.</li><li>Explicit constraints: +10 each, capped at +30.</li><li>Highest schema exposure: +40; blocked lifecycle: +35; security review lifecycle: +40.</li><li>Recorded missing route: +15; Artemis production branch divergence: +25; stale FCC recovery bundle: +20.</li><li>High ≥ 60; Elevated ≥ 30; Lower &lt; 30. Zero only means no scoring signals were found.</li></ul><p>Inspect any project for its contributing facts and source paths. Rule version: risk-v0.1. No weights were supplied by the owner; these are explicitly proposed heuristics.</p></div>`;}
function inboxView(){
 const rows=filterEvents(eventRows,eventLog,eventFilters);
 const productsWithEvents=[...new Set(eventRows.map(e=>e.subject.product_id).filter(Boolean))] as string[];
 const connectorsWithEvents=[...new Set(eventRows.map(e=>e.source.connector))];
 const countable=kpiEligible(eventRows).length;
 const name=(id?:string)=>id?esc(projects.find(p=>p.id===id)?.name??id):'—';
 return `<div class="banner"><b>${eventRows.length} events · ${eventRows.length} simulated · ${countable} countable.</b> Every row below comes from <code>fixtures/events/*.json</code> and is labelled <b>SIMULATED</b>. v0.2 has no event source: nothing is received, no webhook exists, and a simulated event never reaches a KPI — the countable figure above is derived by excluding them, not asserted.</div>
<div class="filters"><select id="event-product" aria-label="Product"><option value="">All products</option>${productsWithEvents.map(id=>`<option value="${esc(id)}" ${eventFilters.product===id?'selected':''}>${name(id)}</option>`).join('')}</select>
<select id="event-connector" aria-label="Connector"><option value="">All connectors</option>${connectorsWithEvents.map(c=>`<option value="${esc(c)}" ${eventFilters.connector===c?'selected':''}>${esc(c)}</option>`).join('')}</select>
<select id="event-severity" aria-label="Severity"><option value="">All severities</option>${[...severities].reverse().map(sv=>`<option value="${sv}" ${eventFilters.severity===sv?'selected':''}>${pretty(sv)}</option>`).join('')}</select>
<select id="event-decision" aria-label="Requires decision"><option value="">Decision: any</option><option value="true" ${eventFilters.requiresDecision==='true'?'selected':''}>Requires a decision</option><option value="false" ${eventFilters.requiresDecision==='false'?'selected':''}>No decision needed</option></select>
<select id="event-status" aria-label="Status"><option value="">All statuses</option>${eventStatuses.map(st=>`<option value="${st}" ${eventFilters.status===st?'selected':''}>${pretty(st)}</option>`).join('')}</select>
<button class="quiet" id="event-reset">Reset</button></div>
<div class="section-heading"><h2>Events <span id="event-count">${rows.length}</span></h2><span>Severity first, then most recent</span></div>
<div class="table-scroll" tabindex="0" aria-label="Event inbox, scrollable"><table id="inbox"><thead><tr>${['Event','Product','Connector','Severity','Decision','Status','Occurred'].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(e=>{
 const status=currentStatus(eventLog,e.id);
 return `<tr data-event="${esc(e.id)}" data-severity="${esc(e.severity)}" data-status="${esc(status)}"><th scope="row"><span class="badge-row" role="group" aria-label="${esc(eventLine(e,status))}">${badge(e.severity==='critical'||e.severity==='warning'?'blocked':'observed',e.severity)}${isSimulated(e)?badge('inferred','SIMULATED'):''}</span><b>${esc(e.type)}</b><small>${esc(e.summary)}</small></th><td>${name(e.subject.product_id)}</td><td>${esc(e.source.connector)}</td><td>${esc(e.severity)}</td><td>${e.requires_decision?'requires a decision':'no'}</td><td>${esc(status)}</td><td>${esc(e.occurred_at)}</td></tr>`;
}).join(''):'<tr><td colspan="7">No matching events. Reset the filters to see all of them.</td></tr>'}</tbody></table></div>
<div class="panel"><h2>What the inbox does not do</h2><ul>
<li><b>Nothing is received.</b> There is no webhook receiver, no polling and no provider client. A local webhook receiver is v0.6 work and needs its own ADR (OG-EVT-004).</li>
<li><b>Nothing is counted.</b> ${eventRows.length} simulated events produce ${countable} countable events. Simulated records are excluded from every KPI, exactly as the v0.1 approval simulation is.</li>
<li><b>Nothing is edited.</b> Events are append-only: a status change is a new record carrying <code>correlation_id</code>, never a change to the original. The status column is the fold over those records.</li>
<li><b>No personal data.</b> Fixtures hold no name, address, message body or machine identifier; the loader refuses a record that carries one, and summaries are capped so a body cannot be smuggled in.</li>
<li><b>Duplicates are removed once.</b> ${eventDuplicates} duplicate provider delivery ${eventDuplicates===1?'was':'were'} dropped on <code>(connector, provider_event_id)</code> before this table was built.</li>
</ul></div>`;}
function connectorsView(){
 const defs=connections.connectors;
 const total=connections.connections.length;
 return `<div class="banner"><b>${defs.length} connectors defined · ${total} connections registered · every one at level 0.</b> A definition records what a connector would be allowed to do and the minimum scopes each level would need. It authorizes nothing: the application contains no service client, no credential field, no enable toggle and no action executor.</div>
<div class="section-heading"><h2>Connection lifecycle</h2><span>docs/04 §3 — v0.2 never leaves the first state</span></div>
<ol class="lifecycle" aria-label="Connection lifecycle states">${lifecycleStates.map((st,i)=>`<li class="${i===0?'current':''}"><b>${esc(st)}</b>${i===0?'<small>where every connection stands today</small>':''}</li>`).join('')}</ol>
<p class="muted">Moving out of <b>REGISTERED</b> means the owner signing in on the provider's own site and a credential being stored outside this application. That flow does not exist in v0.2, so no connection can leave the first state.</p>
<div class="section-heading"><h2>Connections</h2><span>Level 0 of 0–4 · nothing has ever synced</span></div>
<div class="connector-grid">${defs.map(d=>{
 const cs=connectionsOf(connections,d.id);
 const raise=canRaiseLevel(d,0,1,false);
 return `<article class="panel connection-card" data-connector-card="${esc(d.id)}" aria-label="${esc(connectorSummary(d,cs))}">
 <div class="card-top"><h2>${esc(d.provider)}</h2>${badge('blocked','Level 0 · Registered')}</div>
 <p class="muted">Authentication <b>${esc(d.auth)}</b> · ceiling level <b>${d.maxLevel}</b> (${esc(levelNames[d.maxLevel as Level])})</p>
 ${cs.map(c=>`<dl class="card-facts">
  <dt>Account</dt><dd>${esc(c.accountLabel)}</dd>
  <dt>Products</dt><dd>${c.productIds.length?c.productIds.map(id=>esc(projects.find(p=>p.id===id)?.name??id)).join(' · '):'none associated'}</dd>
  <dt>Level</dt><dd>${c.level} — ${esc(levelNames[c.level as Level])}</dd>
  <dt>State</dt><dd>${esc(c.state)}</dd>
  <dt>Granted scopes</dt><dd>${c.grantedScopes.length?c.grantedScopes.map(esc).join(', '):'none granted'}</dd>
  <dt>Last successful sync</dt><dd>${c.lastSuccessfulSync?esc(c.lastSuccessfulSync):'never'}</dd>
  <dt>Webhook health</dt><dd>${esc(c.webhookHealth)}</dd>
  <dt>Credential</dt><dd>${esc(c.credentialStatus)}</dd>
  <dt>Data freshness</dt><dd>${esc(c.dataFreshness)}</dd>
  <dt>Approved actions</dt><dd>${c.approvedActions.length?c.approvedActions.map(esc).join(', '):'none'}</dd>
 </dl>${c.note?`<small>${esc(c.note)}</small>`:''}`).join('')||'<p class="muted">No connection registered for this connector.</p>'}
 <h3>Would observe</h3><ul>${d.observations.map(o=>`<li>${esc(o)}</li>`).join('')||'<li>nothing declared</li>'}</ul>
 <h3>Minimum scopes per level</h3>${d.scopes.map(g=>`<p class="scope"><b>Level ${g.level} — ${esc(levelNames[g.level as Level])}:</b> <code>${g.scopes.map(esc).join('</code> <code>')}</code><small>${esc(g.why)}</small></p>`).join('')}
 <p class="muted" data-raise="${esc(d.id)}">Raising the level: ${esc(raise.reason)}</p>
 <div class="owner-actions" role="group" aria-label="Owner actions for ${esc(d.provider)} — all disabled in v0.2">${ownerActions.map(a=>`<button class="quiet" disabled data-owner-action="${esc(d.id)}:${a}" title="${esc(ownerActionReason[a])}">${pretty(a)}</button>`).join('')}</div>
 <ul class="disabled-reasons">${ownerActions.map(a=>`<li><b>${pretty(a)}:</b> ${esc(ownerActionReason[a])}</li>`).join('')}</ul>
 <button class="quiet" data-connector="${esc(d.id)}">Inspect disabled response</button><pre class="connector-result" id="result-${esc(d.id)}" hidden></pre>
 </article>`;}).join('')}</div>
<div class="panel"><h2>What a definition contains</h2><pre>ConnectorDefinition {
  id, provider, auth: none | oauth | token | webhook-secret | local,
  resources[], observations[], events[], actions[],
  maxLevel: 0-4,                 // ceiling set by owner decision, not by code
  scopes: [{ level, scopes[], why }],
  docs                           // provider documentation, read at block start
}</pre><p>A connection's level can never exceed its connector's <code>maxLevel</code>; <code>config/connectors.json</code> fails to load if it does, and <code>tests/connections.test.ts</code> proves it for every connector. Level 4 (controlled automation) is never available to a connector whose ceiling is lower, and no connector in this build declares an action at all.</p><p class="muted">Full contract: docs/04-CONNECTOR-CONTRACT.md. The five entries above are the same five adapters v0.1 shipped disabled; each still returns a blocked observation without touching the network.</p></div>`;}
function bindView(){
 bindCopy(app);
 for(const [id,key] of [['event-product','product'],['event-connector','connector'],['event-severity','severity'],['event-decision','requiresDecision'],['event-status','status']] as [string,keyof EventFilters][]){
  const el=app.querySelector<HTMLSelectElement>('#'+id);if(el)el.onchange=()=>{eventFilters[key]=el.value;render();};
 }
 {const r=app.querySelector<HTMLButtonElement>('#event-reset');if(r)r.onclick=()=>{Object.assign(eventFilters,emptyEventFilters);render();};}
 app.querySelectorAll<HTMLElement>('[data-workflow]').forEach(b=>b.onclick=()=>showWorkflow(b.dataset.workflow!));
 app.querySelectorAll<HTMLElement>('[data-connector]').forEach(b=>b.onclick=async()=>{const c=connectors.find(c=>c.id===b.dataset.connector)!;const response=await c.collect({projectIds:['agoraxai-web']});const target=app.querySelector<HTMLElement>('#result-'+c.id)!;target.hidden=false;target.textContent=JSON.stringify(response,null,2);});
 app.querySelectorAll<SVGElement>('[data-node]').forEach(b=>{const focus=()=>{mapSelected=mapSelected===b.dataset.node?'':b.dataset.node!;render();};b.onclick=focus;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();focus();}};});
 const mapFocus=app.querySelector<HTMLSelectElement>('#map-focus');if(mapFocus)mapFocus.onchange=()=>{mapSelected=mapFocus.value;render();};
 const mapFilter=app.querySelector<HTMLSelectElement>('#map-kind');if(mapFilter)mapFilter.onchange=()=>{mapKind=mapFilter.value;render();};
{const preset=app.querySelector<HTMLSelectElement>('#map-preset');if(preset)preset.onchange=()=>{mapPreset=preset.value as Preset;mapSelected='';render();};}
 const colour=app.querySelector<HTMLSelectElement>('#map-colour');if(colour)colour.onchange=()=>{mapColour=colour.value as ColourDimension;render();};
 const zin=app.querySelector<HTMLButtonElement>('#zoom-in');if(zin)zin.onclick=()=>{mapZoom=Math.min(2,mapZoom+.25);render();};
 const zout=app.querySelector<HTMLButtonElement>('#zoom-out');if(zout)zout.onclick=()=>{mapZoom=Math.max(.75,mapZoom-.25);render();};
 const resetMap=app.querySelector<HTMLButtonElement>('#map-reset');if(resetMap)resetMap.onclick=()=>{mapZoom=1;mapKind='';mapSelected='';mapPreset='portfolio';mapColour='lifecycle';render();};
 const exportButton=app.querySelector<HTMLButtonElement>('#export-log');if(exportButton)exportButton.onclick=()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify({label:'LOCAL SIMULATION — NOT REAL APPROVALS',...workspace},null,2)],{type:'application/json'}));a.href=url;a.download='octopus-local-simulation.json';a.click();URL.revokeObjectURL(url);};
 const reset=app.querySelector<HTMLButtonElement>('#reset-workflow');if(reset)reset.onclick=()=>{const d=app.querySelector<HTMLDialogElement>('#detail')!;d.innerHTML='<h2 id="detail-title">Reset local simulation?</h2><p>This removes this browser’s simulated transitions and log. The original registry and proposals are unchanged. Export first if you need to retain the simulation.</p><button id="confirm-reset" class="primary">Reset local simulation</button> <button id="cancel-reset" class="quiet">Cancel</button>';d.showModal();d.querySelector<HTMLButtonElement>('#cancel-reset')!.onclick=()=>d.close();d.querySelector<HTMLButtonElement>('#confirm-reset')!.onclick=()=>{workspace=fresh();try{localStorage.removeItem(storageKey);}catch{}notice='Simulation reset. Source proposals remain unapproved.';d.close();render();};};
}
render();

// OG-REG-007/008: reviewable declared organization data in the existing Ecosystem view.
function organizationView():string {
 const label=(id:string)=>catalog.subjects.find(s=>s.id===id)?.label??id;
 const rollup=internalRollup(catalog,catalog.tenancies.map(t=>({id:t.id,value:1})));
 const relations=catalog.edges.filter(e=>['owns','controls','provides_services_to','pays_for_services','client_of','funds'].includes(e.type));
 return `<section id="organization-model"><h2>Declared ownership and tenancy</h2>
 <p>Business ownership does not establish ownership of domains, repositories, software or other IP. Tenancy and service relationships grant no resource access. Partner holders, interests and percentages remain undeclared.</p>
 <div class="table-scroll" tabindex="0" aria-label="Declared subjects and tenancy"><table><thead><tr><th>Subject</th><th>Tenancy</th><th>Provenance and limits</th></tr></thead><tbody>${catalog.subjects.map(s=>`<tr><th>${esc(s.label)}<small>${esc(s.id)}</small></th><td>${esc(s.tenancy)}</td><td>${badge(s.truth)} ${esc(s.source)}<p>${esc(s.note)}</p></td></tr>`).join('')}</tbody></table></div>
 <h3>Declared relationships</h3><ul class="reason-list">${relations.map(e=>`<li><b>${esc(label(e.from))} → ${esc(e.type)} → ${esc(label(e.to))}</b> ${badge(e.truth)}<p>${esc(e.label)}</p><small>${esc(e.source)}</small></li>`).join('')}</ul>
 <h3>Scoped interests</h3><ul>${catalog.shares.map(s=>`<li>${esc(label(s.holderId))} · ${esc(s.scopeType)} ${esc(label(s.scopeId))} · interest: ${esc(s.interest)} · percentage: <b>${esc(percentageLabel(s))}</b><small> ${esc(s.source)}${s.percentage==='undeclared'?' · Attribution blocked: percentage undeclared.':''}</small></li>`).join('')||'<li>No holder-specific interest declared.</li>'}</ul>
 <h3>Internal organization roll-up</h3><p>${rollup.ok?esc(rollup.value):badge('blocked')+' '+esc(rollup.reasons.join('; '))}</p>
 </section>`;
}
